/**
 * The simple photos (model photos@1): the heading, a description and the photos as a list. Axes: cols (2, 3, 4
 * columns from md up; a pair at 4/3, more as squares).
 */
import { type ReactNode } from "react";
import { Block, Container, List, ListItem, Stack, Text, Title } from "../compose";
import { MediaFrame } from "../components/media-frame";
import { cn } from "../utils";
import type { SimplePhoto } from "./photos-simple.types";

export type PhotosSimpleProps = {
  id: string;
  title: string;
  description?: string;
  photos: SimplePhoto[];
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  align?: "start" | "center" | "end";
  cols?: "2" | "3" | "4";
  landmarkLabel?: string;
};

export function PhotosSimple({
  id,
  title,
  description = "",
  photos,
  level = 2,
  padding = "standard",
  align = "center",
  cols = "4",
  landmarkLabel,
}: PhotosSimpleProps) {
  const titleId = id + "-title";
  const column =
    (align as string) === "center" ? "center"
    : (align as string) === "end" ? "end"
    : "start";
  const textAlign =
    (align as string) === "center" ? "text-center"
    : (align as string) === "end" ? "text-end"
    : "text-start";
  const itemsAlign =
    (align as string) === "center" ? "items-center"
    : (align as string) === "end" ? "items-end"
    : "items-start";
  const selfAlign =
    (align as string) === "center" ? "self-center"
    : (align as string) === "end" ? "self-end"
    : "";
  const grid =
    (cols as string) === "2" ? "md:grid-cols-2"
    : (cols as string) === "3" ? "md:grid-cols-3"
    : "md:grid-cols-4";
  const ratio = ((cols as string) === "2") ? "4/3" : "1/1";
  return (
    <Block
      tag="section"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="photos-simple"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Stack gap="12" align="stretch">
          <Stack gap="4" align={column} className={cn("max-w-2xl", selfAlign)}>
            <Title as={level} size="3xl" weight="bold" className={cn("tracking-tight", textAlign)} id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="base" className={cn("text-muted-foreground", textAlign)}>
                {description}
              </Text>
            ) : null}
          </Stack>
          <List tag="ul" className={cn("m-0 list-none p-0", cn("grid grid-cols-2 gap-4", grid))}>
            {(photos ?? []).map((p) => (
              <ListItem key={p.id} data-slot="photo">
                <MediaFrame alt={p.imageAlt} src={p.image} ratio={ratio} />
              </ListItem>
            ))}
          </List>
        </Stack>
      </Container>
    </Block>
  );
}

